import{_ as t,o as i,c as o,ao as s}from"./chunks/framework.ucUddl5u.js";const u=JSON.parse('{"title":"Discovery & Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"extend/discovery.md","filePath":"extend/discovery.md","lastUpdated":null}'),a={name:"extend/discovery.md"};function n(l,e,r,d,p,c){return i(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="Discovery-and-Configuration" tabindex="-1">Discovery &amp; Configuration <a class="header-anchor" href="#Discovery-and-Configuration" aria-label="Permalink to &quot;Discovery &amp; Configuration {#Discovery-and-Configuration}&quot;">​</a></h1><p>Two questions decide which plugins run and what they apply to: <em>which extension packages does a project load</em>, and <em>which project am I in</em>. Ship of Tools answers both explicitly — an <code>[sot]</code> table in the project&#39;s <code>Project.toml</code>, and an outermost-<code>Project.toml</code> root rule. This page covers both, and how a path is resolved to a <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.FileType"><code>FileType</code></a> at runtime once the right packages are loaded.</p><h2 id="Enabling-plugins:-the-sot.extensions-key" tabindex="-1">Enabling plugins: the <code>[sot].extensions</code> key <a class="header-anchor" href="#Enabling-plugins:-the-sot.extensions-key" aria-label="Permalink to &quot;Enabling plugins: the \`[sot].extensions\` key {#Enabling-plugins:-the-sot.extensions-key}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Design, not yet shipped</p><p>The <code>[sot].extensions</code> mechanism on this page is the <strong>committed design</strong> (ADR 0006) but is <strong>not implemented yet</strong>: nothing reads the <code>[sot]</code> table. What works today: the seven standard plugins load automatically with the kernel, and the HDF5 example lazy-loads on the first <code>.h5</code> preview through the kernel&#39;s built-in extension table (<code>LAZY_PLUGIN_FOR_EXT</code> in <code>julia/kernel/src/ShipToolsKernel.jl</code>). A third-party plugin loads only from a source checkout: add it to <code>julia/kernel</code>&#39;s environment, then either add it to the kernel&#39;s <code>using</code> list or map its file extension in <code>LAZY_PLUGIN_FOR_EXT</code>. The kernel has a <code>plugins.load</code> op, but no client sends it. On a release install the kernel lives inside the pinned release checkout, and local changes there make the next update refuse to run.</p></div><p>A plugin&#39;s <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.FileType"><code>FileType</code></a> subtype is discovered automatically <em>once the package is loaded</em> — but <strong>whether</strong> a package loads is an explicit choice, not an auto-scan. The design: the project&#39;s <code>Project.toml</code> carries a <code>[sot]</code> table listing the extensions to load:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">extensions = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HDF5Preview&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MyOrgPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The kernel calls <code>Base.require</code> on each entry at startup, in declared order, before serving any requests. Anything not listed is <strong>not loaded, even if it is installed</strong> in the active environment.</p><p>The alternative — auto-scanning loaded packages for <code>ConceptExplorerCore</code> dependents — was rejected in favour of this explicit list. The reasoning:</p><ul><li><p><strong>Predictable.</strong> No magic load order, no &quot;why is this plugin active?&quot; debugging.</p></li><li><p><strong>Visible.</strong> Adding a plugin is three explicit steps — install it, add it to <code>extensions</code>, restart the kernel.</p></li><li><p><strong>Compatible with static tool registration.</strong> The full plugin set is known at kernel startup.</p></li></ul><p>Because there is no auto-discovery, plugins are discoverable only through documentation — so a plugin README should lead with its install + enable snippet.</p><h2 id="Project-root-detection" tabindex="-1">Project-root detection <a class="header-anchor" href="#Project-root-detection" aria-label="Permalink to &quot;Project-root detection {#Project-root-detection}&quot;">​</a></h2><p>The kernel needs one unambiguous answer to &quot;what project is this?&quot; The rule:</p><ul><li><p>Walk upward from the current directory until a <code>Project.toml</code> is found. That directory is the project root.</p></li><li><p>In monorepos with nested <code>Project.toml</code> files (umbrella + sub-packages), the <strong>outermost</strong> one — highest in the tree — wins by default.</p></li><li><p>Override with the backend&#39;s <code>--project &lt;path&gt;</code> flag.</p></li><li><p>If no <code>Project.toml</code> is found before the filesystem root, the backend exits with an error telling you to run inside a Julia project or pass <code>--project</code>.</p></li></ul><p>The kernel then activates that environment (<code>Pkg.activate(&lt;root&gt;)</code>), and plugin discovery reads <code>[sot].extensions</code> from that <strong>same</strong> <code>Project.toml</code>. Root detection and plugin loading are anchored on one file.</p><h2 id="Runtime-resolution:-path-FileType" tabindex="-1">Runtime resolution: path → FileType <a class="header-anchor" href="#Runtime-resolution:-path-FileType" aria-label="Permalink to &quot;Runtime resolution: path → FileType {#Runtime-resolution:-path-FileType}&quot;">​</a></h2><p>With the right packages loaded, resolving a path to a renderer is two functions in <code>ConceptExplorerCore</code>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Function</th><th style="text-align:right;">Returns</th><th style="text-align:right;">Behaviour</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.file_types-Tuple{}"><code>file_types</code></a><code>()</code></td><td style="text-align:right;"><code>Vector{Type{&lt;:FileType}}</code></td><td style="text-align:right;">every loaded subtype — <code>subtypes(FileType)</code></td></tr><tr><td style="text-align:right;"><a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.file_type_for-Tuple{AbstractString}"><code>file_type_for</code></a><code>(path)</code></td><td style="text-align:right;"><code>Union{Type{&lt;:FileType}, Nothing}</code></td><td style="text-align:right;">first subtype whose <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.matches"><code>matches</code></a> is <code>true</code>, else <code>nothing</code></td></tr></tbody></table><p><code>file_type_for</code> walks <code>file_types()</code> in order; for each subtype it checks there is a <code>matches(::Type{T}, path)</code> method and calls it, returning the <strong>first</strong> type that claims the path. When nothing claims it, the result is <code>nothing</code> — a visible &quot;no plugin handles this&quot; rather than a guessed render. Once a type is chosen, the kernel calls <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.preview"><code>preview</code></a> (and, where wired, <a href="/ship-of-tools/dev/ref/api-core#ConceptExplorerCore.parse_entities"><code>parse_entities</code></a>) on it.</p><p>This is why enabling a plugin is enough to make its file kind previewable: load the package (via <code>extensions</code>), and its subtype joins the <code>file_types()</code> scan that <code>file_type_for</code> walks. No central registry, no Rust change. See <a href="./abi">The Dispatch ABI</a> for the contract behind these calls and <a href="./filetype">Writing a FileType Plugin</a> for implementing <code>matches</code> / <code>preview</code>.</p><h2 id="A-complete-sot-snippet" tabindex="-1">A complete <code>[sot]</code> snippet <a class="header-anchor" href="#A-complete-sot-snippet" aria-label="Permalink to &quot;A complete \`[sot]\` snippet {#A-complete-sot-snippet}&quot;">​</a></h2><p>A project that enables the HDF5 example plus a hypothetical org plugin:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MyProject&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uuid = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... your project&#39;s own dependencies ...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">extensions = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HDF5Preview&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MyOrgPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>The extension packages themselves must be resolvable in the project&#39;s environment (added to <code>[deps]</code> or otherwise on the load path), since <code>Base.require</code> loads them by name.</p><div class="tip custom-block"><p class="custom-block-title">Phase-2 diagnostic</p><p>There is no auto-discovery of installed-but-unenabled plugins today. A possible <code>--list-installed-extensions</code> diagnostic is flagged for a later phase to surface candidates you have not enabled yet.</p></div><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><p><a href="./filetype">Writing a FileType Plugin</a> — <code>matches</code> / <code>preview</code> implementation.</p></li><li><p><a href="./hdf5">Worked Example: HDF5</a> — enabling a real external plugin.</p></li><li><p><a href="./../ref/api-core">API — ConceptExplorerCore</a> — <code>file_types</code>, <code>file_type_for</code>.</p></li></ul>`,26)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
